arguments.command:
for spec in 'n2033 n2032' 'n2082 n2081' 'n2137 n2136' 'n2192 n2191'; do set -- $spec; ./op read-nodes "$1" --depth 20 --page "$2" | python3 -c 'import json,sys; from collections import Counter; d=json.load(sys.stdin); r=d["nodes"][0];
def walk(n):
 yield n
 for c in n.get("children",[]): yield from walk(c)
ns=list(walk(r)); ts=[n for n in ns if n.get("type")=="text"]; fs=[(n.get("fontSize"),n.get("id")) for n in ts if isinstance(n.get("fontSize"),(int,float))]; out=[(n.get("id"),n.get("name"),n.get("x"),n.get("y"),n.get("width"),n.get("height")) for n in ns[1:] if all(isinstance(n.get(k),(int,float)) for k in ("x","y","width","height")) and (n["x"]<0 or n["y"]<0 or n["x"]+n["width"]>r["width"] or n["y"]+n["height"]>r["height"])]; tipo=[(n.get("id"),n.get("x"),n.get("y"),n.get("width"),n.get("height")) for n in ts if n.get("content")=="TIPO"]; overlaps=[]
for i,a in enumerate(tipo):
 for b in tipo[i+1:]:
  if max(a[1],b[1])<min(a[1]+a[3],b[1]+b[3]) and max(a[2],b[2])<min(a[2]+a[4],b[2]+b[4]): overlaps.append((a[0],b[0]))
names=Counter(n.get("name") for n in ns if n.get("name")); dup=[(k,v) for k,v in names.items() if v>1]; attr=[(n.get("id"),n.get("content")) for n in ts if "ATRIBUTOS DEL TIPO" in n.get("content","")]; print({"root":r.get("id"),"size":[r.get("width"),r.get("height")],"nodes":len(ns),"texts":len(ts),"minFont":min((x[0] for x in fs),default=None),"below12":[x for x in fs if x[0]<12],"outsideRoot":out,"exactTIPO":tipo,"TIPOoverlaps":overlaps,"duplicateNames":dup,"attributeTableHeadings":attr})'; done

